# Function to get gene expression for a cell
def get_cell_markers(cell_id, markers):
    scores = []
    for gene in markers:
        if gene in adata.var_names:
            idx = adata.obs_names.tolist().index(cell_id)
            scores.append(adata.X[idx, adata.var_names.tolist().index(gene)].toarray()[0][0] if hasattr(adata.X, 'toarray') else adata.X[idx, adata.var_names.tolist().index(gene)])
        else:
            scores.append(0)
    return np.mean(scores), np.max(scores)

# Score each cell
results = {}
for cell_id in cell_ids:
    gd_mean, gd_max = get_cell_markers(cell_id, gammadelta_markers)
    treg_mean, treg_max = get_cell_markers(cell_id, treg_markers)
    results[cell_id] = {
        'gammadelta_mean': gd_mean, 'gammadelta_max': gd_max,
        'treg_mean': treg_mean, 'treg_max': treg_max
    }

